export class ConsoleFilter{constructor(){this.init();}init(){(function(){const originalWarn=console.warn;const originalLog=console.log;const suppressPatterns=[ /installHook\.js/i,/EternlDomAPI/i,/initEternlDomAPI/i,/overrideMethod/i,/chrome-extension:/i,/moz-extension:/i ];console.warn=function(...args){const message=args.join(' ');const shouldSuppress=suppressPatterns.some(pattern=> pattern.test(message));if(!shouldSuppress){originalWarn.apply(console,args);}};console.log=function(...args){const message=args.join(' ');const shouldSuppress=suppressPatterns.some(pattern=> pattern.test(message));if(!shouldSuppress){originalLog.apply(console,args);}};console.log('🧹 [CONSOLE] Extension warning filter active');})();}}export async function cachedFetch(url,options={}){const requestCache=new Map();const pendingRequests=new Map();async function cachedFetch(url,options={}){const cacheKey=`${url}:${JSON.stringify(options)}`;if(requestCache.has(cacheKey)){const{data,timestamp}=requestCache.get(cacheKey);if(Date.now()- timestamp < 5000){console.log(`✅ [CACHE HIT] ${url}`);return data;}}if(pendingRequests.has(cacheKey)){console.log(`⏳ [DEDUP] Waiting for in-flight request:${url}`);return pendingRequests.get(cacheKey);}const promise=fetch(url,options).then(r=> r.json()).then(data=>{requestCache.set(cacheKey,{data,timestamp:Date.now()});pendingRequests.delete(cacheKey);return data;}).catch(err=>{pendingRequests.delete(cacheKey);throw err;});pendingRequests.set(cacheKey,promise);return promise;}}